public class ReferralCheckIn {static boolean valid(String s){return s!=null&&s.length()==4&&s.charAt(0)=='G'&&Character.isDigit(s.charAt(1))&&Character.isDigit(s.charAt(2))&&Character.isUpperCase(s.charAt(3));}static String process(GymMember[]m){int p=0,n=0,g=0;for(GymMember x:m)if(x==null)n++;else{p++;if(x instanceof GroupClassMember)g++;}return p+" processed | "+n+" null skipped | "+g+" group";}public static void main(String[]a){System.out.println(valid("G45B"));}}
